def main():
 p=argparse.ArgumentParser();p.add_argument('--write',action='store_true');a=p.parse_args()
 dest=ROOT/'work/ui/battle_0.1.13/generated'
 rows=[]
 for r in SPEC:
  source=Path(r['source']);assert source.is_file()
  rows.append(dict(resource=r['resource'],file=str(r['resource'])+'.png',sha256=hashlib.sha256(source.read_bytes()).hexdigest(),prompt=r['prompt'],source=str(source)))
 print(json.dumps(dict(mode='write' if a.write else 'dry-run',pages=len(rows),sample=rows[0]),indent=2))
 if a.write:
  dest.mkdir()
  for r in rows:shutil.copyfile(r['source'],dest/r['file'])
  (dest/'index.json').write_text(json.dumps(dict(version='0.1.13',method='built-in image_gen',assets=rows),indent=2)+'\n',encoding='utf-8')
if __name__=='__main__':main()

